<?php
declare(strict_types=1);
namespace App\Controllers; use App\Core\Request;use App\Core\View;use App\Core\Response;use App\Core\Session;use App\Middleware\PermissionMiddleware;use App\Repositories\CategoryRepository;
final class CategoryController { public function index(Request $r):void{PermissionMiddleware::require('categories.view');$repo=new CategoryRepository();$rows=in_array(auth_user()['role_name']??'', ['Super Admin','Admin'], true)?$repo->all():$repo->allForUser((int)Session::get('user_id'));View::render('categories/index',compact('rows'));} public function store(Request $r):void{PermissionMiddleware::require('categories.create');verify_csrf();(new CategoryRepository())->create($r->all(),(int)Session::get('user_id'));Session::flash('success','Category created.');Response::redirect('/categories');} public function update(Request $r,string $id):void{PermissionMiddleware::require('categories.edit');verify_csrf();if(($r->input('customize')??'')==='1'){PermissionMiddleware::require('categories.customize');(new CategoryRepository())->customize((int)$id,(int)Session::get('user_id'),$r->all());Session::flash('success','Category badge customized.');}else{(new CategoryRepository())->update((int)$id,$r->all());Session::flash('success','Category updated.');}Response::redirect('/categories');} public function delete(Request $r,string $id):void{PermissionMiddleware::require('categories.delete');verify_csrf();(new CategoryRepository())->delete((int)$id);Session::flash('success','Category deleted.');Response::redirect('/categories');}}
